<script>
(function () {
  var section = document.getElementById('svsSection');
  var isMobile = window.innerWidth <= 768;
  var videoMb = document.getElementById('svsVideoMb');
  var videoPc = document.getElementById('svsVideo');
  var video = isMobile ? videoMb : videoPc;

  if (!section) return;

  // Pause video không cần thiết
  if (isMobile && videoPc) videoPc.pause();
  if (!isMobile && videoMb) videoMb.pause();

  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        if (video) {
          video.muted = true;
          video.load();
          video.play().catch(function () {});
        }
        section.classList.add('svs-in-view');
      } else {
        if (video) video.pause();
      }
    });
  }, { threshold: 0.25 });

  observer.observe(section);
})();
</script>

